values ((select id from public.teams limit 1), $il$i057$il$, $il$Filter by group in Outreach$il$, $il$Lovable UI$il$, $il$Brad$il$, $il$nice$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:22:41.000Z'::timestamptz, 5, '{}'::text[], array[$il$i047$il$]::text[], null, null, false, false, $il${}$il$::jsonb,
$il$Brad's suggestion on the call and Oliver agreed. Once groups exist, being able to filter outreach by group means you can see every live conversation across a group before touching any of it. Depends on i047.$il$,
$il$$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i058$il$, $il$One contact can belong to more than one company$il$, $il$Data & schema$il$, $il$Brad$il$, $il$must$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:23:41.000Z'::timestamptz, 1, '{}'::text[], '{}'::text[], null, null, false, false, $il${}$il$::jsonb,
$il$Dr. Boris Ewenstein exists twice at Otto, once with the title and once without, and the dedup did not catch it. The underlying reason a strict rule was never applied: Oliver sometimes works the same person at two companies, which a one contact one company model cannot express.

Fix both at once. Allow a contact to be linked to several companies. Then enforce the strict rule that made impossible: one LinkedIn URL per contact, and a new contact matching an existing URL is flagged rather than created.$il$,
$il$THE TITLE IS WHY THE DUPLICATE SURVIVED, and it is dealt with separately in i059. Dedup on a name string will keep failing while titles, middle names and umlaut spellings live in the same field.

MATCH ON THE URL, NOT THE NAME. A profile identifier is the only thing on a LinkedIn contact that is unique and stable. Names are not: two Christians at MediaMarkt, five suggested for one message in the reconciliation queue.

WHICH COMPANY OWNS THE OUTREACH when a contact has two. Probably the one the conversation is about, set per touch rather than per contact. Worth deciding before building, or the touch history ends up on the wrong company record.$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i059$il$, $il$Academic title as its own field$il$, $il$Data & schema$il$, $il$Brad$il$, $il$nice$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:24:41.000Z'::timestamptz, 1, '{}'::text[], '{}'::text[], null, null, false, false, $il${}$il$::jsonb,
$il$Dr. Boris Ewenstein is held with the title inside the first name, which is how the duplicate got past the check. Split it: academic title, first name, last name. Dr, Prof, Prof Dr.

It also matters for German drafting. A salutation reading Hallo Dr. Boris is wrong, and Sehr geehrter Herr Dr. Ewenstein is right, so the title has to be addressable separately from the name.$il$,
$il$$il$);

