values ((select id from public.teams limit 1), $il$i060$il$, $il$Contact ID visible on the contact overview$il$, $il$Lovable UI$il$, $il$Brad$il$, $il$nice$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:25:41.000Z'::timestamptz, 5, '{}'::text[], '{}'::text[], null, null, false, false, $il${}$il$::jsonb,
$il$The contact id exists as the last column of the contacts table, but it disappears the moment a contact is opened. Put it on the overview of the individual contact so it can be quoted in a message to Brad or in these notes.$il$,
$il$$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i061$il$, $il$Every draft says why it was written, and why now$il$, $il$Outreach & drafting$il$, $il$Both$il$, $il$must$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:26:41.000Z'::timestamptz, 4, array[$il$i067$il$]::text[], '{}'::text[], null, null, false, false, $il${}$il$::jsonb,
$il$Under each draft, a short plain summary of how it was built: which layer or agent produced it, which facts it used, and what triggered it now. Oliver cannot currently tell whether a message came from the executive assistant, the email architect, the LinkedIn architect or the voice file, and when something reads wrong there is no way to find out where it went wrong.

The why now half is the more valuable one. Reasons like they accepted the connection request, or they posted that they are looking for a provider, are prioritisation signal as well as an explanation, and can bump the score.$il$,
$il$THE FAILURE THIS CATCHES, in Oliver's words: it was classifying greenfield opportunities that were not greenfield, because something was silently dropped or decided. A wrong verdict inside a confident looking draft is invisible. Showing the inputs makes it visible in the second it takes to read the line.

IT IS ALREADY HALF BUILT. There is a Why this now field on the outreach card, and the AI state of play panel on the contact view is doing the harder version of this well. This item is extending that to the draft itself: not only why this person now, but why THIS message.

KEEP IT TO ONE OR TWO LINES. If it becomes a paragraph nobody reads it, and an unread explanation is the same as none.$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i062$il$, $il$There is no way to archive a company, and archiving must keep it findable$il$, $il$Data & schema$il$, $il$Brad$il$, $il$must$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:27:41.000Z'::timestamptz, 3, '{}'::text[], '{}'::text[], null, null, false, false, $il${}$il$::jsonb,
$il$AB Gsmshop.at GmbH is marked OoS and the only action on the record is Move to Monday, which is the wrong destination for an out of scope company. There is no Archive at all. Add one, reachable from the company header.

WHEN IT ARCHIVES it should ask why and store the reason, and carry the company's contacts, touch points and outreach notes with it rather than leaving them loose. Archived with no explanation is indistinguishable from archived by mistake, and six months later nobody can tell which.

ARCHIVE MUST NOT MEAN HIDDEN FROM SEARCH. An out of scope company has to stay findable, because the whole point of recording it was so we never spend research credits on it twice. Archiving takes it out of worklists, queues and counts. It does not take it out of the search box.

So: Out of Scope is the REASON, archive is the SHELF. Do not make one automatically imply the other, and do not let the shelf swallow the record.$il$,
$il$THE STANDING RULE THIS PROTECTS: log every company found, including a non fit, marked Out of Scope with the reason, so the same company is never researched twice. An archive that removes a company from search would quietly break that rule, and the failure is invisible. Somebody sources it again in three months and nobody notices it was already ruled out.

WHAT SHOULD DISAPPEAR ON ARCHIVE: worklists, the sourcing queue, the ranked list in i071, draft creation, and the headline counts. What should NOT: search, the company id resolving, and the record itself when someone lands on it from a note or an old link.

IT PAIRS WITH THE GROUP CASES. The Conrad and Save Group collisions both end in archive with a reason rather than a deletion, and the reason is the whole value: worked in Monday under the parent, or ruled out as B2B only. An archive with no reason turns into a mystery the first time anyone asks why the company is not in the pipeline.

AND IT NEEDS AN UNDO, or at least a visible archived filter with a restore. Brad already offers Archived only as a toggle on contacts, so the pattern exists; the company side needs the same.$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i063$il$, $il$Set the follow-up while sending the reply, and default it to automatic$il$, $il$Outreach & drafting$il$, $il$Both$il$, $il$must$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:28:41.000Z'::timestamptz, 3, '{}'::text[], array[$il$i036$il$]::text[], null, null, false, false, $il${}$il$::jsonb,
$il$Next to Send on a reply, a follow-up setter. Presets of a week, a month, six months, and a custom date from a calendar, so a reply saying come back in January can be scheduled as 12 January on the spot.

The default is AUTO. The system reads the reply and picks the date itself, so a follow-up exists even when Oliver forgets to set one. He can always override. In his words, it should never be possible for a conversation to go silent.

This applies to replies Oliver sends. Everything else is already inside a funnel and keeps the cadence it has.$il$,
$il$AUTO HAS TO SHOW ITS WORKING, which is i061 again. When the chaser surfaces, it should say promised follow up in January, so Oliver can see why it is due today and trust it. An automatic date with no visible reason is the thing people switch off.

BRAD'S POINT IS RIGHT AND WORTH HOLDING: a contact who says come back in January is still cold, so the lead stays where it is rather than being promoted. The follow-up is a date, not a status change.

THIS IS THE SAME MECHANISM AS i036, seen from the other end. i036 is the activity area on the record; this is setting one at the moment of sending. Build one scheduler and surface it in both places, not two.$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i064$il$, $il$A message sent outside Lovable still gets a follow-up$il$, $il$Integrations$il$, $il$Brad$il$, $il$must$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:29:41.000Z'::timestamptz, 3, '{}'::text[], array[$il$i036$il$]::text[], null, null, false, false, $il${}$il$::jsonb,
$il$Oliver replied to Urs Moeller directly in LinkedIn. The inbox watcher will pick that up on its next run, which is right. What must also happen is that the follow-up logic fires on it.

So: any send detected from outside the system defaults to automatic AI chasing, same as i063. It is the failsafe. Nothing that leaves Pier should be able to go silent just because it was sent in the wrong window.$il$,
$il$$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i065$il$, $il$Show when LinkedIn next syncs, and let it be triggered by hand$il$, $il$Lovable UI$il$, $il$Brad$il$, $il$nice$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:30:41.000Z'::timestamptz, 5, '{}'::text[], '{}'::text[], null, null, false, false, $il${}$il$::jsonb,
$il$The LinkedIn sync runs every four hours and there is no way to see when the next one is. Oliver wants it fixed in the top bar, next to the dark mode toggle, reading something like next LinkedIn sync at 14:00, so he can plan a batch of sends around it.

Alongside it, a manual trigger. Brad has this planned for the next version. Keep both: the schedule so nothing depends on somebody pressing a button, and the trigger for when Oliver has just done an hour of connection requests and wants them picked up now.$il$,
$il$$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i066$il$, $il$Moving a parent to Monday must not archive the rest of the group$il$, $il$Guards$il$, $il$Brad$il$, $il$must$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:31:41.000Z'::timestamptz, 2, '{}'::text[], array[$il$i044$il$]::text[], null, null, false, false, $il${}$il$::jsonb,
$il$Telia Sweden is the parent and has moved to Monday. Denmark, Finland and Norway are still lake companies and should stay workable.

Oliver's reasoning: there are several roads into a group. Sometimes the subsidiary is the way in, and sometimes a country has no insurance at all while the parent does. So moving one company to Monday marks that company only, shows the group link, and leaves the siblings alone.

It is the opposite requirement to the Monday suppression in i044, and both are right. Suppress a company that is being worked elsewhere. Do not suppress its sisters unless they are being worked too.$il$,
$il$$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i067$il$, $il$Sign-offs are wrong, including one draft signed with Brad's name$il$, $il$Voice$il$, $il$Brad$il$, $il$must$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:32:41.000Z'::timestamptz, 4, '{}'::text[], array[$il$i061$il$]::text[], null, null, false, false, $il${}$il$::jsonb,
$il$Drafts are signing off inconsistently and sometimes with the wrong person entirely.
  Oli, seen on at least four drafts. Oliver never signs outbound that way.
  Oliver Mueller in full on others, so it is not a single wrong constant.
  BRAD, on the 8 September regenerated draft for Florian Pfeiffer. Another person's name, on Oliver's message, one click from being sent.

The canonical rule already exists in the voice file: external communications sign as Oliver, never Ollie. So this is not a preference being violated, it is a written rule not reaching the drafter.

Trace it rather than patch it. Something is supplying a name from the wrong place, and whatever does that will be getting other things from the wrong place too.$il$,
$il$THE INCONSISTENCY IS THE CLUE. If every draft signed Oli it would be one bad constant. Some sign Oli, some sign Oliver Mueller, and one signs Brad. That points at more than one generation path, or at the sign off being inferred from context rather than set from the voice layer. Brad appearing suggests it can pick up whoever is associated with the session or the record rather than the sender.

WORTH CHECKING WHICH LAYERS ACTUALLY LOAD at draft time, which is i061. If the sign off is wrong, other rules from the same file are probably also not landing, and nobody would notice because the rest are less visible than a name at the bottom.

A DRAFT SIGNED BRAD IS A REPUTATION RISK, not a typo. It reads as a message written by somebody else on Oliver's behalf, which is precisely the impression the whole voice layer exists to avoid. Worth a lint rule that fails any draft whose sign off is not Oliver, rather than relying on the prompt, per i084 and the enforcement over prose principle.$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i068$il$, $il$Verify every company group and subsidiary against the web, once$il$, $il$Research agent$il$, $il$Both$il$, $il$must$il$, $il$open$il$, $il$Oliver$il$, '2026-09-15T12:33:41.000Z'::timestamptz, 1, '{}'::text[], array[$il$i047$il$]::text[], null, null, false, false, $il${}$il$::jsonb,
$il$Brad's suggestion, and a good one. A single long agent run across all companies that checks group and subsidiary relationships against the web and reports what is wrong, rather than Oliver correcting 1,400 records by hand.

It must HIGHLIGHT rather than change. Oliver reviews and approves, because a wrong parent written confidently is worse than no parent at all.

The Recommerce case shows why it is needed and why it is hard: Recommerce Group in France, Recommerce AG, and verkaufen.ch were separate until Recommerce Group acquired Recommerce AG through its Swiss subsidiary RS Switzerland SA in June 2025. A relationship that is true today was false eighteen months ago, so every finding needs a date and a source.$il$,
$il$RUN IT AFTER i047, not before. Without somewhere structured to put a parent, a subsidiary and a relationship type, the run produces a list nobody can apply.

EVERY LINK LANDS UNVERIFIED until a person confirms it, same rule as i047. An agent reading a website is evidence, not proof, and the Save Group and asgoodasnew case shows how a probable ownership note hardens into an assumed fact if nothing marks it as unconfirmed.

IT WILL ALSO FIND THE DUPLICATES, which feeds i056. Recommerce appears four times, including one with a stray exclamation mark from an old character recognition pass.$il$);

